replace_once('adapters/opencode/tbag.js','''      entry.done = true\n      if (follows.get(key) === entry) follows.delete(key)\n      queueWake(client, sessionID)\n''','''      entry.done = true\n      if (follows.get(key) === entry) follows.delete(key)\n      persistTransport(args.run_root)\n      queueWake(client, sessionID)\n''')
